// Independent Host analysis of frozen stages proven word-identical in the
// Observed DSP graph. No DSP arithmetic helper is included or invoked.
#define PHONELM_PRECISION_LIBRARY
#include "upstream_precision_test.cpp"
#include "double_qk_fixture.h"
int main(int argc,char** argv){std::cout<<std::setprecision(17);try{if(argc!=4)return 1;auto fs=segmentstudy::lnCases(one::read(argv[1]));auto more=precision::synthetic();fs.insert(fs.end(),more.begin(),more.end());auto ds=doubleqkfixture::load(argv[2]);auto ms=mixedfixture::load(argv[3]);double identity=0;
 for(unsigned ci=0;ci<60;++ci){auto& z=fs[ci];auto c=one::lncase(z);c.x=z.v.at("layerinput");c.gamma=z.v.at("gamma1");c.beta=z.v.at("beta1");auto l=precision::idealLn(c);auto q=one::mm(l.y,one::d(z.v.at("wq")),32,64,64),k=one::mm(l.y,one::d(z.v.at("wk")),32,64,64);auto v=one::mm(l.y,one::d(ms[ci].w[2]),32,64,64);std::cout<<"{\"kind\":\"upstream_stage\",\"case\":"<<ci<<",\"set\":"<<(ci<44?0:1)<<",\"ln_Y_cumulative\":"<<attribution::distance(l.y,one::d(ms[ci].y))<<",\"Q_cumulative\":"<<attribution::distance(q,one::d(ms[ci].expected[1][0]))<<",\"K_cumulative\":"<<attribution::distance(k,one::d(ms[ci].expected[1][1]))<<",\"V_cumulative\":"<<attribution::distance(v,one::d(ms[ci].expected[1][2]))<<"}\n";
  for(unsigned h=0;h<2;++h){auto raw=one::mm(one::split(q,h),one::split(k,h),32,32,32,false,true),scaled=one::mul(raw,{double(probabilitycontract::scale())}),masked=probabilitycontract::masked(scaled),p=one::softmax(masked);auto& a=ds[ci];auto actualRaw=one::d(a.expected[1][h]),actualScale=one::d(a.scaled[h]),actualMask=one::d(a.masked[h]);auto localScale=one::mul(actualRaw,{double(probabilitycontract::scale())}),localMask=one::add(actualScale,one::d(probabilitycontract::mask()));double allowed=0,future=0;for(unsigned r=0;r<32;++r)for(unsigned col=0;col<32;++col){auto i=r*32+col;auto& maximum=col<=r?allowed:future;maximum=std::max(maximum,std::fabs(masked[i]-actualMask[i]));}identity=std::max(identity,attribution::distance(p,a.idealP[0][h]));std::cout<<"{\"kind\":\"score_stage\",\"case\":"<<ci<<",\"set\":"<<(ci<44?0:1)<<",\"head\":"<<h<<",\"raw_local_double\":"<<attribution::distance(a.local[h],actualRaw)<<",\"raw_cumulative\":"<<attribution::distance(raw,actualRaw)<<",\"scale_local_double\":"<<attribution::distance(localScale,actualScale)<<",\"scale_cumulative\":"<<attribution::distance(scaled,actualScale)<<",\"mask_local_double\":"<<attribution::distance(localMask,actualMask)<<",\"mask_cumulative\":"<<attribution::distance(masked,actualMask)<<",\"mask_allowed_cumulative\":"<<allowed<<",\"mask_future_cumulative\":"<<future<<",\"P_ideal_softmax_of_FP32_masked_vs_R0\":"<<attribution::distance(p,a.localP[h])<<"}\n";}
 }
 if(identity!=0)throw std::runtime_error("independent ideal P reference mismatch");std::cout<<"{\"kind\":\"stage_attribution_summary\",\"cases\":60,\"heads\":120,\"ideal_reference_mismatch\":0,\"DSP_EXECUTION\":false,\"condition\":\"Frozen stage values require actual DSP observed word identity; invisible intermediates not directly measured\"}\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 4;}}
